public void makeWorkflow()
{
    TFMWorkflowsTable wfTable = TFMWorkflowsTable::Find(TFMConstants::WorkflowStandard());

    next makeWorkflow();

    if (wfTable) // Don't add if the workflow already existed
    {
        return;
    }
    wfTable = TFMWorkflowsTable::Find(TFMConstants::WorkflowStandard());

    wftable.addOnlineValidation(methodStr(MobOnlineValidator,GetSerialNumberInformation), MobConstants::Pick(), enum2Symbol(enumNum(MobWorkflowValidationTypes), MobWorkflowValidationTypes::serialNumberValidation));
    wftable.addOnlineValidation(methodStr(MobOnlineValidator,LocationValidation), MobConstants::Pick(), enum2Symbol(enumNum(MobWorkflowValidationTypes), MobWorkflowValidationTypes::fromBinValidation));
    wftable.addOnlineValidation(methodStr(MobOnlineValidator,quantityValidation), MobConstants::Pick(), enum2Symbol(enumNum(MobWorkflowValidationTypes), MobWorkflowValidationTypes::quantityValidation));
    wftable.addOnlineValidation(methodStr(MobOnlineValidator,ValidateBatchNumber), MobConstants::Pick(), enum2Symbol(enumNum(MobWorkflowValidationTypes), MobWorkflowValidationTypes::lotNumberValidation));
    wftable.addOnlineValidation(methodStr(MobOnlineValidator,toteValidation), MobConstants::Pick(), enum2Symbol(enumNum(MobWorkflowValidationTypes), MobWorkflowValidationTypes::toteValidation));

}
